package org.apache.commons.math.geometry;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.apache.commons.math.exception.MathArithmeticException;
import org.apache.commons.math.exception.util.LocalizedFormats;
import org.apache.commons.math.util.FastMath;
import org.apache.commons.math.util.MathUtils;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class Vector3D_crossProduct_TriageGen2Test {

    private static final double EPSILON = 1e-10;

    @Test
    public void testCrossProduct_StandardBasis() {
        Vector3D i = new Vector3D(1.0, 0.0, 0.0);
        Vector3D j = new Vector3D(0.0, 1.0, 0.0);
        Vector3D k = new Vector3D(0.0, 0.0, 1.0);

        // i x j = k
        Vector3D result1 = Vector3D.crossProduct(i, j);
        assertVectorEquals(k, result1);

        // j x i = -k
        Vector3D result2 = Vector3D.crossProduct(j, i);
        assertVectorEquals(k.negate(), result2);

        // j x k = i
        Vector3D result3 = Vector3D.crossProduct(j, k);
        assertVectorEquals(i, result3);

        // k x j = -i
        Vector3D result4 = Vector3D.crossProduct(k, j);
        assertVectorEquals(i.negate(), result4);
    }

    @Test
    public void testCrossProduct_ParallelVectors() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D v2 = new Vector3D(2.0, 4.0, 6.0); // v2 = 2 * v1
        Vector3D zero = new Vector3D(0.0, 0.0, 0.0);

        // Cross product of parallel vectors should be zero vector
        Vector3D result = Vector3D.crossProduct(v1, v2);
        assertVectorEquals(zero, result);
    }

    @Test
    public void testCrossProduct_ZeroVector() {
        Vector3D v1 = new Vector3D(1.0, 2.0, 3.0);
        Vector3D zero = new Vector3D(0.0, 0.0, 0.0);

        // v1 x 0 = 0
        Vector3D result1 = Vector3D.crossProduct(v1, zero);
        assertVectorEquals(zero, result1);

        // 0 x v1 = 0
        Vector3D result2 = Vector3D.crossProduct(zero, v1);
        assertVectorEquals(zero, result2);
    }

    @Test
    public void testCrossProduct_ArbitraryVectors() {
        Vector3D v1 = new Vector3D(3.0, -3.0, 1.0);
        Vector3D v2 = new Vector3D(4.0, 9.0, 2.0);

        // Expected calculation:
        // x = (-3 * 2) - (1 * 9) = -6 - 9 = -15
        // y = (1 * 4) - (3 * 2) = 4 - 6 = -2
        // z = (3 * 9) - (-3 * 4) = 27 + 12 = 39
        Vector3D expected = new Vector3D(-15.0, -2.0, 39.0);
        Vector3D result = Vector3D.crossProduct(v1, v2);

        assertVectorEquals(expected, result);
    }

    @Test
    public void testCrossProduct_NegativeComponents() {
        Vector3D v1 = new Vector3D(-1.0, -2.0, -3.0);
        Vector3D v2 = new Vector3D(4.0, 5.0, 6.0);

        // x = (-2 * 6) - (-3 * 5) = -12 + 15 = 3
        // y = (-3 * 4) - (-1 * 6) = -12 + 6 = -6
        // z = (-1 * 5) - (-2 * 4) = -5 + 8 = 3
        Vector3D expected = new Vector3D(3.0, -6.0, 3.0);
        Vector3D result = Vector3D.crossProduct(v1, v2);

        assertVectorEquals(expected, result);
    }

    @Test
    public void testCrossProduct_LargeValues() {
        Vector3D v1 = new Vector3D(1e10, 0.0, 0.0);
        Vector3D v2 = new Vector3D(0.0, 1e10, 0.0);
        Vector3D expected = new Vector3D(0.0, 0.0, 1e20);

        Vector3D result = Vector3D.crossProduct(v1, v2);

        Assert.assertEquals(expected.getX(), result.getX(), EPSILON);
        Assert.assertEquals(expected.getY(), result.getY(), EPSILON);
        Assert.assertEquals(expected.getZ(), result.getZ(), 1e15); // Larger epsilon for massive scale
    }

    private void assertVectorEquals(Vector3D expected, Vector3D actual) {
        Assert.assertEquals("X component mismatch", expected.getX(), actual.getX(), EPSILON);
        Assert.assertEquals("Y component mismatch", expected.getY(), actual.getY(), EPSILON);
        Assert.assertEquals("Z component mismatch", expected.getZ(), actual.getZ(), EPSILON);
    }
}
